DAYS = ["8", "9"]  # 8: 평일, 9: 휴일, 7: 토요일 (기본은 8·9만)
HERE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "kric_out")
os.makedirs(HERE, exist_ok=True)
PART = os.path.join(HERE, "kric_partial.json")
OUT = os.path.join(HERE, "kric_timetable.json.gz")

def fetch(key, op, ln, stin, day):
    q = urllib.parse.urlencode({"serviceKey": key, "format": "json", "railOprIsttCd": op,
                                "lnCd": ln, "stinCd": stin, "dayCd": day})
    url = "https://openapi.kric.go.kr/openapi/trainUseInfo/subwayTimetable?" + q
    r = subprocess.run(["curl", "-sS", "--max-time", "20", url], capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(r.stderr.strip())
    data = json.loads(r.stdout)
    header = data.get("header", {})
    code = header.get("resultCode")
    if code == "30":  # 등록되지 않은 서비스키
        raise KeyError(header.get("resultMsg", "인증키 오류"))
    if code not in ("00", "03"):  # 03: 데이터 없음
        raise RuntimeError(json.dumps(header, ensure_ascii=False))
    return [[b.get("trnNo"), b.get("arvTm"), b.get("dptTm")] for b in (data.get("body") or [])]

def main():
    key = os.environ.get("KRIC_KEY") or getpass.getpass("레일포털 인증키를 붙여 넣고 Enter (화면에 안 보임): ")
    key = key.strip().strip("'\"")
    if not key.startswith("$2a$"):
        sys.exit(f"인증키 모양이 이상합니다 (길이 {len(key)}, 앞 4글자 '{key[:4]}'). $2a$로 시작해야 합니다.")
    print(f"인증키 확인: 길이 {len(key)}, 앞 4글자 '{key[:4]}', 뒤 3글자 '{key[-3:]}'")
    done = json.load(open(PART, encoding="utf-8")) if os.path.exists(PART) else {}
    # 옵션: --day 7 --line 2호선  처럼 특정 요일·노선만 다시 받을 수 있음
    days, line_only = DAYS, None
    args = sys.argv[1:]
    if "--day" in args:
        days = [args[args.index("--day") + 1]]
    if "--line" in args:
        line_only = args[args.index("--line") + 1].split(",")  # 쉼표로 여러 노선: --line 3호선,4호선
    stations = [s for s in STATION_LIST if line_only is None or s[2] in line_only]
    print(f"받을 것: 요일 {', '.join(days)} / {', '.join(line_only) if line_only else '전체 노선'} / 역 {len(stations)}개")
    jobs = [(s, d) for s in stations for d in days]
    total = len(jobs)
    for i, (s, day) in enumerate(jobs, 1):
        op, ln, lnname, stin, name = s
        k = f"{day}|{op}|{ln}|{stin}"
        if k in done:
            continue
        for attempt in range(3):
            try:
                done[k] = {"line": lnname, "name": name, "rows": fetch(key, op, ln, stin, day)}
                break
            except KeyError as e:
                sys.exit(f"레일포털이 인증키를 거부했습니다: {e}\n키를 다시 확인해 주세요. 브라우저 테스트에 썼던 키와 같은지 보세요.")
            except Exception as e:
                print(f"  다시 시도 {attempt + 1}/3: {name} ({lnname}) - {e}")
                time.sleep(5)
        else:
            print(f"  건너뜀: {name} ({lnname})")
        if i % 20 == 0 or i == total:
            json.dump(done, open(PART, "w", encoding="utf-8"), ensure_ascii=False)
            print(f"{i}/{total} 완료 ({lnname} {name})")
        time.sleep(1.0)
    json.dump(done, open(PART, "w", encoding="utf-8"), ensure_ascii=False)
    with gzip.open(OUT, "wt", encoding="utf-8") as f:
        json.dump(done, f, ensure_ascii=False, separators=(",", ":"))
    empty = [v["name"] + "(" + v["line"] + ")" for v in done.values() if not v["rows"]]
    print("끝! 저장한 파일:", OUT)
    if empty:
        print("데이터가 없던 역", len(empty), "개:", ", ".join(empty[:20]))

if __name__ == "__main__":
    main()
